* @param {any} params.imports
* @param {ApiHelpers} params.helpers

function handler({api, event, helpers, imports}) {
    const value = event.payload.value;

    api.setState(
        'select_building',
        Array.isArray(value) ? value[0] : value
    );
}

function handler({api, event, helpers, imports}) {

    const value = event.payload.value;
    const predio = Array.isArray(value) ? value[0] : value;

    api.setState('select_building', predio);

    // Ao mudar o prédio, o andar anterior deixa de ser válido
    api.setState('select_floor', '');

    let filters = [];

    if (api.state.select_unit) {
        filters.push('unidade=' + api.state.select_unit);
    }

    if (predio) {
        filters.push('predio=' + predio);
    }

    filters.push('ativo_para_reserva=true');

    api.setState('room_filter', filters.join('^'));
}
